/**
 * The editor gutter's git marks, derived from the file's unified diff.
 *
 * A mark is keyed by the buffer's own (new-file) line number, which is the line
 * the editor draws. A run of deletions followed by insertions is one modified
 * block; a lone insertion is added; a lone deletion is marked at the line it
 * collapsed onto.
 */
import type { GitDiffHunk } from '@deepseek-ai/dsh-api-remotes/client'

/** What one gutter line reports. */
export type GitMark = 'added' | 'modified' | 'deleted'

/** One hunk header's starting line numbers, from its @@ -a,b +c,d @@ text. */
function starts(header: string): { readonly old: number; readonly next: number } {
  const parsed = /^@@ -(\d+)(?:,\d+)? \+(\d+)(?:,\d+)? @@/u.exec(header)
  return { old: Number.parseInt(parsed?.[1] ?? '1', 10), next: Number.parseInt(parsed?.[2] ?? '1', 10) }
}

/**
 * Build the per-line marks of one comparison.
 * @param hunks - the file's diff hunks, in file order.
 * @returns marks keyed by one-based new-file line number.
 */
export function gutterMarks(hunks: readonly GitDiffHunk[]): ReadonlyMap<number, GitMark> {
  const marks = new Map<number, GitMark>()
  for (const hunk of hunks) {
    const start = starts(hunk.header)
    let line = start.next
    let index = 0
    const lines = hunk.lines
    while (index < lines.length) {
      const current = lines[index]
      if (current === undefined) break
      if (current.kind === 'delete') {
        let deleted = 0
        while (lines[index]?.kind === 'delete') {
          deleted += 1
          index += 1
        }
        let inserted = 0
        while (lines[index]?.kind === 'add') {
          inserted += 1
          const target = line + inserted - 1
          marks.set(target, deleted > 0 ? 'modified' : 'added')
          index += 1
        }
        if (inserted === 0) marks.set(Math.max(1, line), 'deleted')
        line += inserted
        continue
      }
      if (current.kind === 'add') {
        marks.set(line, 'added')
        line += 1
        index += 1
        continue
      }
      line += 1
      index += 1
    }
  }
  return marks
}
