/**
 * Session manager, browser half: the Session row menu's **Delete session** row,
 * and the right Sidebar's **Trash** tab that browses what the deletes hold.
 *
 * The Remote namespace is mounted on first use, because deployments built
 * before it entered their static Client assembly do not carry it.
 */
import type { Context as ClientContext } from '@deepseek-ai/cordis'
import type { ClientRemote } from '@deepseek-ai/dsh-api-remotes/client'
import type {} from '@deepseek-ai/dsh-api-remotes/client'
import sessionManagerRemote from '@deepseek-ai/dsh-api-session-manager-controller/remote'
import type {} from '@deepseek-ai/dsh-client-locale/client'
import type {} from '@deepseek-ai/dsh-client-ui-renderer/client'
import type {} from '@deepseek-ai/dsh-client-ui-sidebar-right/client'
import type { HostObservable } from '@deepseek-ai/dsh-client-ui-slots'
import type {} from '@deepseek-ai/dsh-client-ui-slots'
import type {} from '@deepseek-ai/dsh-client-ui-workspace/client'
import { DeleteSessionMenuItem } from './DeleteSession.tsx'
import { TRASH_ID, TRASH_KIND, trashDefinition } from './definition.tsx'
import { en, NS, zh, type SessionManagerLocaleKey } from './locales.ts'
import { FilesOverlay, type FilesOverlayInjected } from './FileDragShim.tsx'
import { FilesRailIcon, TerminalRailIcon } from './RailGlyphs.tsx'
import { TrashPanel, type TrashInjected } from './TrashPanel.tsx'
import { TrashRailIcon } from './TrashRailIcon.tsx'
import { TrashTitle } from './TrashTitle.tsx'

declare module '@deepseek-ai/dsh-client-ui-slots' {
  interface LocaleNamespaceMap {
    /** Session manager copy. */
    sessionManager: SessionManagerLocaleKey
  }
}

/** Services this plugin reads: slots, its dictionaries, the Remote store, and the right Sidebar's tab registry. */
export const inject = ['slots', 'locale', 'remote', 'sidebarRightTabs']

/** The injected delete gesture. */
export interface DeleteSessionInjected {
  /** Move one Session's log into the trash and archive it. */
  readonly deleteSession: (sessionId: string, displayTitle: string) => void
}

/**
 * Contribute the Delete session row and the Trash tab.
 * @param ctx - the browser plugin context.
 */
export function apply(ctx: ClientContext): void {
  ctx.effect(() => ctx.locale.register(NS, { zh, en }), 'ui-session-manager: dictionaries')
  const t = ctx.locale.bind(NS)
  let mounting: Promise<void> | undefined
  const ensureRemote = async (): Promise<void> => {
    if (ctx.get('remote.sessionManager') !== undefined) return
    mounting ??= (async () => {
      try {
        await ctx.remote.$mount(sessionManagerRemote)
      } catch (error) {
        if (ctx.get('remote.sessionManager') === undefined) throw error
      } finally {
        mounting = undefined
      }
    })()
    await mounting
  }
  const service = (): ClientRemote['sessionManager'] => {
    const found: ClientRemote['sessionManager'] | undefined = ctx.get('remote.sessionManager')
    if (found === undefined) throw new Error('sessionManager: remote namespace is unavailable')
    return found
  }

  // One revision counter tells an already-open Trash tab that the set moved;
  // without it the tab keeps the snapshot it loaded on mount.
  let trashRevision = 0
  const trashListeners = new Set<() => void>()
  const trashChanges: HostObservable<number> = {
    getSnapshot: () => trashRevision,
    subscribe: (listener) => {
      trashListeners.add(listener)
      return () => { trashListeners.delete(listener) }
    },
  }
  const movedTrash = (): void => {
    trashRevision += 1
    for (const listener of [...trashListeners]) listener()
  }

  ctx.slots.inject('sidebar.workspaces.session.menu.item', () => ctx.slots.register({
    name: 'sidebar.workspaces.session.menu.item',
    id: 'delete',
    order: 450,
    locale: NS,
    inject: (): DeleteSessionInjected => ({
      deleteSession: (sessionId, displayTitle) => {
        void ensureRemote()
          .then(() => service().delete({ sessionId, displayTitle }))
          .then(() => { movedTrash() })
          .catch((reason: unknown) => {
            // The log may still have moved before the Remote rejected, so the
            // Trash list is told to re-read either way.
            movedTrash()
            console.warn('session delete rejected:', reason)
          })
      },
    }),
  }, DeleteSessionMenuItem))

  // The trash browser: a right Sidebar tab the frame's rail opens by kind, with
  // the same three gestures the Host Remote offers.
  ctx.effect(() => ctx.sidebarRightTabs.register(trashDefinition(t)), 'ui-session-manager: trash type')
  const trashInjected = (): TrashInjected => ({
    hooks: { trashRevision: trashChanges },
    list: async () => {
      await ensureRemote()
      const result = await service().listTrash()
      return result.ok ? result.value : []
    },
    restore: async (name) => {
      await ensureRemote()
      return service().restoreTrash({ name })
    },
    purge: async (name) => {
      await ensureRemote()
      return service().purgeTrash({ name })
    },
  })
  ctx.slots.inject('sidebar.right.pane.tab', () => ctx.slots.register({
    name: 'sidebar.right.pane.tab',
    key: TRASH_ID,
    locale: NS,
    inject: trashInjected,
  }, TrashPanel))
  ctx.slots.inject('sidebar.right.pane.tab.title', () => ctx.slots.register({
    name: 'sidebar.right.pane.tab.title',
    key: TRASH_ID,
  }, TrashTitle))
  // The in-box file rows gain their drag source and git tint from outside the panel.
  ctx.slots.inject('shell.overlay', () => ctx.slots.register({
    name: 'shell.overlay',
    id: 'files-overlay',
    inject: (): FilesOverlayInjected => ({
      status: async (cwd) => {
        await ensureRemote()
        const result = await service().gitStatus({ cwd })
        return result.ok ? result.value : { available: false, files: {} }
      },
      open: (absolutePath) => { ctx.get('editorNavigation')?.open(absolutePath) },
    }),
  }, FilesOverlay))
  ctx.slots.inject('rightrail', () => ctx.slots.register({
    name: 'rightrail',
    id: TRASH_KIND,
    // Last in the rail: the high order keeps the utility below the tools.
    order: 1000,
    label: () => t('trash.title'),
    locale: NS,
  }, TrashRailIcon))
  // The Files and Terminal packages in older deployments predate the rail, so
  // their entries come from here; the ids are their surface kinds, which is what
  // the frame asks the right column to toggle.
  ctx.slots.inject('rightrail', () => ctx.slots.register({
    name: 'rightrail',
    id: 'files',
    order: 10,
    label: () => t('rail.files'),
    locale: NS,
  }, FilesRailIcon))
  ctx.slots.inject('rightrail', () => ctx.slots.register({
    name: 'rightrail',
    id: 'terminal',
    order: 45,
    label: () => t('rail.terminal'),
    locale: NS,
  }, TerminalRailIcon))
}
