/** The trash tab's chip title: the trash glyph before the type's label. */
import type { ReactNode } from 'react'
import { IconTrashOutlineRegular } from '@deepseek-ai/dsh-client-ui-primitives'
import type { PropsRuntime } from '@deepseek-ai/dsh-client-ui-slots'
import css from './TrashPanel.module.css'

/**
 * The title as the chip shows it.
 * @param props - the tab information hook.
 * @returns the trash glyph followed by the tab's title text.
 */
export function TrashTitle({ useTabInfo }: PropsRuntime<'sidebar.right.pane.tab.title'>): ReactNode {
  const { tab } = useTabInfo()
  return (
    <>
      <IconTrashOutlineRegular size={16} className={css.titleIcon} />
      {tab.title}
    </>
  )
}
