/** The Trash entry on the frame's right rail. */
import type { ReactNode } from 'react'
import { IconTrashOutlineRegular } from '@deepseek-ai/dsh-client-ui-primitives'
import type { PropsLocale, PropsRuntime } from '@deepseek-ai/dsh-client-ui-slots'
import type { NS } from './locales.ts'

/** Full component props assembled by the frame's rail renderer. */
export type TrashRailIconProps = PropsRuntime<'rightrail'> & PropsLocale<typeof NS>

/**
 * Render the trash glyph.
 * @param props - the rail's icon edge.
 * @returns the glyph.
 */
export function TrashRailIcon({ size }: TrashRailIconProps): ReactNode {
  return <IconTrashOutlineRegular size={size} />
}
