/** Customizations Settings section: this deployment's Skills and MCP servers. */

import type { Context as ClientContext } from '@deepseek-ai/cordis'
import type {} from '@deepseek-ai/dsh-api-remotes/client'
import type {} from '@deepseek-ai/dsh-client-locale/client'
import type {} from '@deepseek-ai/dsh-client-ui-renderer/client'
// Type-only: pulls the Client Session scope adapter merge (ctx.uiSession).
import type {} from '@deepseek-ai/dsh-client-ui-session/client'
import type {} from '@deepseek-ai/dsh-client-ui-settings/client'
import type { ClientRemote, ManagedMcpServer, PluginEntryId } from '@deepseek-ai/dsh-api-remotes/client'
import customizationsRemote from '@deepseek-ai/dsh-api-customizations-controller/remote'
import {
  CustomizationsSection,
  type CustomizationsSessionId,
  type CustomizationsSectionInjected,
} from './CustomizationsSection.tsx'
import type { McpWriteOutcome } from './McpServersList.tsx'
import { en, zh, type CustomizationsLocaleKey } from './locales.ts'

export type { CustomizationsSectionInjected, CustomizationsSectionProps } from './CustomizationsSection.tsx'
export type { CustomizationsLocaleKey } from './locales.ts'

declare module '@deepseek-ai/dsh-client-ui-slots' {
  interface LocaleNamespaceMap {
    /** Customizations section copy. */
    'settings.customizations': CustomizationsLocaleKey
  }
}

/** Dictionary namespace owned by this plugin. */
export const NS = 'settings.customizations'

/** Services required by the Settings registration and the Remotes the pane writes through. */
export const inject = ['slots', 'locale', 'uiSession', 'remote', 'remote.pluginManager']

/**
 * Contribute the Customizations page to the Settings navigation.
 * @param ctx - the browser plugin context.
 */
export function apply(ctx: ClientContext): void {
  ctx.effect(() => ctx.locale.register(NS, { zh, en }), 'ui-settings-customizations: dictionaries')

  const t = ctx.locale.bind(NS)
  // Older deployments do not mount this Remote in their static Client assembly;
  // mount our own generated contribution on first read, after boot has settled.
  let mounting: Promise<void> | undefined
  const ensureRemote = async (): Promise<void> => {
    if (ctx.get('remote.customizations') !== undefined) return
    mounting ??= (async () => {
      try {
        await ctx.remote.$mount(customizationsRemote)
      } catch (error) {
        if (ctx.get('remote.customizations') === undefined) throw error
      } finally {
        mounting = undefined
      }
    })()
    await mounting
  }
  // The namespace is not in this plugin's inject list (it may be mounted on
  // demand above), so read it through the service store instead of the
  // inject-backed property proxy.
  const customizationsService = (): ClientRemote['customizations'] => {
    const service: ClientRemote['customizations'] | undefined = ctx.get('remote.customizations')
    if (service === undefined) throw new Error('customizations: remote namespace is unavailable')
    return service
  }
  const list: CustomizationsSectionInjected['list'] = async (sessionId) => {
    await ensureRemote()
    const result = await customizationsService().snapshot(sessionId)
    if (!result.ok) {
      throw new Error(`customizations.snapshot failed: ${result.error.code}: ${result.error.message}`)
    }
    return result.value
  }
  const setEnabled = async (entryId: string, enabled: boolean): Promise<McpWriteOutcome> => {
    // The Loader handed this id to the Host; the wire carries it back as an opaque string.
    const result = await ctx.remote.pluginManager.setPluginEnabled(entryId as PluginEntryId, enabled)
    if (!result.ok) return { ok: false, message: result.error.code }
    const failure = result.value.error
    if (failure !== undefined) return { ok: false, message: `${failure.code}: ${failure.diagnostic ?? ''}` }
    if (result.value.application === 'failed' || result.value.application === 'cancelled') {
      return { ok: false, message: result.value.application }
    }
    return { ok: true, application: result.value.application }
  }
  const write = async (call: () => Promise<{ ok: boolean; error?: { code: string } }>): Promise<McpWriteOutcome> => {
    await ensureRemote()
    const result = await call()
    return result.ok ? { ok: true, application: 'applied' } : { ok: false, message: result.error?.code ?? 'gateway/internal' }
  }
  const addServer = (server: ManagedMcpServer): Promise<McpWriteOutcome> =>
    write(() => customizationsService().addMcpServer(server))
  const removeServer = (id: string): Promise<McpWriteOutcome> =>
    write(() => customizationsService().removeMcpServer(id))
  const setManagedEnabled = (id: string, enabled: boolean): Promise<McpWriteOutcome> =>
    write(() => customizationsService().setManagedMcpServerEnabled(id, enabled))
  const readBalance: CustomizationsSectionInjected['readBalance'] = async () => {
    await ensureRemote()
    const result = await customizationsService().balance()
    if (!result.ok) throw new Error(`customizations.balance failed: ${result.error.code}`)
    return result.value
  }
  const injected = (): CustomizationsSectionInjected => ({
    hooks: {
      // The main view's Session is the pane's workspace scope: it is the same
      // Session whose conversation and Files panel the user is looking at.
      mainSessionId: {
        // The adapter's binding key is the Session scope this window renders; the
        // brand is nominal typing only, so the wire identity stamps it back here.
        getSnapshot: () => ctx.uiSession.adapter.current.getSnapshot().key as CustomizationsSessionId | undefined,
        subscribe: listener => ctx.uiSession.adapter.current.subscribe(listener),
      },
    },
    list, setEnabled, addServer, removeServer, setManagedEnabled, readBalance,
  })

  ctx.slots.inject('settings.section', () => ctx.slots.register({
    name: 'settings.section',
    id: 'customizations',
    order: 12,
    label: () => t('nav'),
    locale: NS,
    inject: injected,
  }, CustomizationsSection))
}
