/**
 * One plugin, every IDE surface: Source control, Editor, Session trash, Turn
 * deliverables, and Customizations.
 *
 * The five feature clients keep their own slots, dictionaries, and Remote
 * namespaces; composing them here means one Loader row and one install.
 */
import type { Context as ClientContext } from '@deepseek-ai/cordis'
import type { ShortcutCommandId } from '@deepseek-ai/dsh-client-shortcuts/client'
import type {} from '@deepseek-ai/dsh-client-ui-sidebar-right/client'
import { apply as applyGit, inject as gitInject } from '@deepseek-ai/dsh-client-ui-git/client'
import { apply as applyEditor, inject as editorInject } from '@deepseek-ai/dsh-client-ui-editor/client'
import { apply as applySessionManager, inject as sessionManagerInject } from '@deepseek-ai/dsh-client-ui-session-manager/client'
import { apply as applyDeliverables, inject as deliverablesInject } from '@deepseek-ai/dsh-client-ui-deliverables/client'
import { apply as applyCustomizations, inject as customizationsInject } from '@deepseek-ai/dsh-client-ui-settings-customizations/client'

/** Every service the merged surfaces read, deduplicated. */
export const inject = [...new Set([
  ...gitInject,
  ...editorInject,
  ...sessionManagerInject,
  ...deliverablesInject,
  ...customizationsInject,
])]

/**
 * Mount every IDE surface on one fiber.
 * @param ctx - the browser plugin context.
 */
export function apply(ctx: ClientContext): void {
  applyCustomizations(ctx)
  applyDeliverables(ctx)
  applyGit(ctx)
  applyEditor(ctx)
  applySessionManager(ctx)
  // Cmd+J: open the terminal and float it above the editor column's bottom
  // edge, so it reads as a dock without covering the composer.
  ctx.effect(() => ctx.shortcuts.register({
    id: 'workbench.terminalDock' as ShortcutCommandId,
    label: () => 'Terminal at the bottom',
    aliases: ['dock terminal'],
    defaults: {
      'desktop:macos': { code: 'KeyJ', modifiers: ['primary'] },
      'desktop:windows': { code: 'KeyJ', modifiers: ['primary'] },
      'desktop:linux': { code: 'KeyJ', modifiers: ['primary'] },
      'web:macos': { code: 'KeyJ', modifiers: ['primary', 'alt'] },
      'web:windows': { code: 'KeyJ', modifiers: ['primary', 'alt'] },
    },
    regions: ['page', 'editable', 'terminal'],
    modals: [],
    resolve: ({ target }) => {
      const commandTarget = ctx.sidebarRight.commandTarget(target)
      if (commandTarget === undefined) return { status: 'blocked', reason: 'Open a session first' }
      return { status: 'handled', run: () => {
        ctx.sidebarRight.openTabFromTarget('terminal', commandTarget)
        const active = ctx.sidebarRight.active()
        if (active === undefined) return
        const width = Math.max(360, Math.round(window.innerWidth * 0.45))
        ctx.sidebarRight.float(active.id, {
          x: window.innerWidth - width - 40,
          y: window.innerHeight - 300,
          width,
          height: 280,
        })
      } }
    },
  }), 'workbench: terminal dock')
}
