/**
 * The `trash` tab type: a page the frame's right rail opens by kind, not a
 * viewer that claims an address.
 */
import { IconTrashOutlineRegular } from '@deepseek-ai/dsh-client-ui-primitives'
import type { SidebarRightTabDefinition } from '@deepseek-ai/dsh-client-ui-sidebar-right/client'
import type { TranslateNS } from '@deepseek-ai/dsh-client-locale/client'
import type {} from './locales.ts'

/** The tab kind this plugin owns. */
export const TRASH_KIND = 'trash'

/** This implementation's identity in the tab system, and the key its body registers under. */
export const TRASH_ID = '@deepseek-ai/dsh-client-ui-session-manager'

/**
 * The trash type's registry definition.
 * @param t - namespace-bound translate, read fresh on every label call.
 * @returns the definition to register.
 */
export function trashDefinition(t: TranslateNS<'sessionManager'>): SidebarRightTabDefinition {
  return {
    id: TRASH_ID,
    kind: TRASH_KIND,
    priority: 'builtin',
    title: () => t('trash.title'),
    // The frame's start page opens the tab by kind; the rail is not part of
    // every deployment.
    guide: [{
      id: 'trash',
      order: 30,
      title: () => t('trash.title'),
      description: () => t('guide.description'),
      icon: IconTrashOutlineRegular,
    }],
  }
}
