/**
 * The trash browser: what the deletes hold, with Restore and Delete forever.
 *
 * The list is loaded once per mount and after every action; the entries are the
 * Host's, so nothing here is derived.
 */
import { useCallback, useEffect, useState } from 'react'
import type { ReactNode } from 'react'
import { Button } from '@deepseek-ai/dsh-client-ui-primitives'
import type { SessionTrashEntry } from '@deepseek-ai/dsh-api-session-manager-controller/types'
import type { HostObservable, InjectFace, PropsLocale, PropsRuntime } from '@deepseek-ai/dsh-client-ui-slots'
import type { NS } from './locales.ts'
import css from './TrashPanel.module.css'

/** What the panel asks the Host. */
export interface TrashInjected {
  /** Moves the Trash set: a delete elsewhere bumps it so an open tab re-reads. */
  readonly hooks: {
    readonly trashRevision: HostObservable<number>
  }
  /** The trash entries, newest first. */
  readonly list: () => Promise<readonly SessionTrashEntry[]>
  /** Move one entry back to its Session directory. */
  readonly restore: (name: string) => Promise<unknown>
  /** Remove one entry for good. */
  readonly purge: (name: string) => Promise<unknown>
}

/** Full component props of the trash body. */
export type TrashPanelProps =
  PropsRuntime<'sidebar.right.pane.tab'>
  & PropsLocale<typeof NS>
  & InjectFace<TrashInjected>

/** One entry's size, with a localized unit. */
const BYTES = new Intl.NumberFormat(undefined, { style: 'unit', unit: 'byte', notation: 'compact', maximumFractionDigits: 1 })

/** One entry's delete time, in the reader's locale. */
const WHEN = new Intl.DateTimeFormat(undefined, { dateStyle: 'short', timeStyle: 'short' })

/**
 * Render the trash list.
 * @param props - the Host actions and the locale seat.
 * @returns the list, or the empty state.
 */
export function TrashPanel({ list, restore, purge, useTrashRevision, t }: TrashPanelProps): ReactNode {
  const revision = useTrashRevision(value => value)
  const [entries, setEntries] = useState<readonly SessionTrashEntry[]>([])
  const [busy, setBusy] = useState(false)
  const refresh = useCallback((): void => {
    void list().then(setEntries).catch(() => { setEntries([]) })
  }, [list])
  useEffect(() => { refresh() }, [refresh, revision])
  const settle = (action: (name: string) => Promise<unknown>, name: string): void => {
    setBusy(true)
    void action(name).then(() => { setBusy(false); refresh() }).catch(() => { setBusy(false) })
  }
  if (entries.length === 0) return <p className={css.empty}>{t('trash.empty')}</p>
  return (
    <ul className={css.list}>
      {entries.map(entry => (
        <li key={entry.name} className={css.row}>
          <span className={css.title} title={entry.title}>{entry.title}</span>
          <span className={css.when}>{WHEN.format(new Date(entry.trashedAt))}</span>
          <span className={css.size}>{BYTES.format(entry.bytes)}</span>
          <span className={css.actions}>
            <Button variant="outline" disabled={busy} onClick={() => { settle(restore, entry.name) }}>
              {t('trash.restore')}
            </Button>
            <Button variant="outline" disabled={busy} onClick={() => { settle(purge, entry.name) }}>
              {t('trash.purge')}
            </Button>
          </span>
        </li>
      ))}
    </ul>
  )
}
