/**
 * The delete action: one `sidebar.workspaces.session.menu.item` row that moves
 * the Session's log into the trash and archives it. The trash makes the action
 * reversible for the retention window, so the row asks for no confirmation.
 */
import type { ReactNode } from 'react'
import { IconTrashOutlineRegular, MenuItemButton } from '@deepseek-ai/dsh-client-ui-primitives'
import type { InjectFace, PropsLocale, PropsRuntime } from '@deepseek-ai/dsh-client-ui-slots'
import type {} from '@deepseek-ai/dsh-client-ui-workspace/client'
import type { DeleteSessionInjected } from './index.ts'
import type { NS } from './locales.ts'

/** Full props of the delete row. */
export type DeleteSessionProps =
  PropsRuntime<'sidebar.workspaces.session.menu.item'>
  & PropsLocale<typeof NS>
  & InjectFace<DeleteSessionInjected>

/**
 * Render the delete row.
 * @param props - the row identity, the injected delete gesture, and the locale seat.
 * @returns the menu row.
 */
export function DeleteSessionMenuItem({ sessionId, displayTitle, useMenuOpenState, deleteSession, t }: DeleteSessionProps): ReactNode {
  const [, setMenuOpen] = useMenuOpenState()
  return (
    <MenuItemButton
      danger
      separatorBefore
      icon={<IconTrashOutlineRegular size={14} />}
      onSelect={() => {
        setMenuOpen(false)
        deleteSession(sessionId, displayTitle)
      }}
    >
      {t('deleteSession')}
    </MenuItemButton>
  )
}
