/**
 * The rail glyphs for surfaces whose own packages predate the rail: the
 * workspace tree and the terminal prompt.
 */
import type { ReactNode } from 'react'
import { IconWorkspaceTreeOutlineRegular } from '@deepseek-ai/dsh-client-ui-primitives'
import type { PropsRuntime } from '@deepseek-ai/dsh-client-ui-slots'

/**
 * The Files rail glyph.
 * @param props - the rail's icon edge.
 * @returns the workspace tree glyph.
 */
export function FilesRailIcon({ size }: PropsRuntime<'rightrail'>): ReactNode {
  return <IconWorkspaceTreeOutlineRegular size={size} />
}

/**
 * The Terminal rail glyph: a prompt mark drawn with `currentColor`, so the rail
 * lights it like any other tool.
 * @param props - the rail's icon edge.
 * @returns the prompt glyph.
 */
export function TerminalRailIcon({ size }: PropsRuntime<'rightrail'>): ReactNode {
  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 16 16"
      fill="none"
      xmlns="http://www.w3.org/2000/svg"
      aria-hidden="true"
      strokeWidth={1.2}
      strokeLinecap="round"
      strokeLinejoin="round"
    >
      <rect x="1.6" y="2.6" width="12.8" height="10.8" rx="2.2" stroke="currentColor" />
      <path d="M4.4 6.2L6.6 8L4.4 9.8" stroke="currentColor" />
      <path d="M7.6 10H11.2" stroke="currentColor" />
    </svg>
  )
}
