/**
 * The document header's Edit action: hands the previewed file to the Editor
 * panel. Registered by the Editor package, so the preview stays unaware of it.
 */
import type { ReactNode } from 'react'
import type {} from '@deepseek-ai/dsh-client-ui-sidebar-documentpreview/client'
import type { InjectFace, PropsLocale, PropsRuntime } from '@deepseek-ai/dsh-client-ui-slots'
import css from './OpenInEditorAction.module.css'

/** The injected open gesture. */
export interface OpenInEditorInjected {
  open: (absolutePath: string) => void
}

/** Full props of the document-header contribution. */
export type OpenInEditorActionProps =
  PropsRuntime<'sidebar.right.tab.document.actions'>
  & PropsLocale<'editor'>
  & InjectFace<OpenInEditorInjected>

/**
 * Render the Edit action in the document header.
 * @param props - the previewed path, the injected open gesture, and the translator.
 * @returns the Edit button.
 */
export function OpenInEditorAction({ absolutePath, open, t }: OpenInEditorActionProps): ReactNode {
  return (
    <button type="button" className={css.action} onClick={() => { open(absolutePath) }}>
      {t('edit')}
    </button>
  )
}
