/**
 * Rendered Markdown for a document the Editor shows as a page instead of a
 * buffer. The subset covers what a repository README uses: headings, paragraphs,
 * lists, block quotes, rules, fenced code, and inline code, bold, italic, and
 * links. Everything is built as React elements, so document text never becomes
 * HTML and cannot inject markup.
 */
import type { ReactNode } from 'react'
import css from './MarkdownView.module.css'

/** Inline tokens: code, bold, italic, and a link. */
const INLINE = /(`[^`]+`|\*\*[^*]+\*\*|\*[^*]+\*|\[[^\]]+\]\([^)]+\))/gu

/**
 * Format one line's inline markup.
 * @param text - the line's text.
 * @param key - stable prefix for the produced keys.
 * @returns the formatted nodes.
 */
function inline(text: string, key: string): ReactNode[] {
  const nodes: ReactNode[] = []
  let index = 0
  for (const match of text.matchAll(INLINE)) {
    const at = match.index ?? 0
    if (at > index) nodes.push(text.slice(index, at))
    const token = match[0]
    const id = `${key}-${String(at)}`
    if (token.startsWith('`')) nodes.push(<code key={id} className={css.inlineCode}>{token.slice(1, -1)}</code>)
    else if (token.startsWith('**')) nodes.push(<strong key={id}>{token.slice(2, -2)}</strong>)
    else if (token.startsWith('*')) nodes.push(<em key={id}>{token.slice(1, -1)}</em>)
    else {
      const link = /^\[([^\]]+)\]\(([^)]+)\)$/u.exec(token)
      if (link === null) nodes.push(token)
      else nodes.push(<a key={id} href={link[2]} target="_blank" rel="noreferrer">{link[1]}</a>)
    }
    index = at + token.length
  }
  if (index < text.length) nodes.push(text.slice(index))
  return nodes
}

/**
 * Render one Markdown document.
 * @param props.text - the document's source.
 * @returns the rendered blocks.
 */
export function MarkdownView({ text }: { readonly text: string }): ReactNode {
  const lines = text.split('\n')
  const blocks: ReactNode[] = []
  let index = 0
  while (index < lines.length) {
    const line = lines[index] ?? ''
    const key = `b${String(index)}`
    const fence = /^```(.*)$/u.exec(line)
    if (fence !== null) {
      const code: string[] = []
      index += 1
      while (index < lines.length && !(lines[index] ?? '').startsWith('```')) {
        code.push(lines[index] ?? '')
        index += 1
      }
      index += 1
      blocks.push(<pre key={key} className={css.code}><code>{code.join('\n')}</code></pre>)
      continue
    }
    const heading = /^(#{1,6})\s+(.*)$/u.exec(line)
    if (heading !== null) {
      const level = (heading[1] ?? '#').length
      const Tag = (['h1', 'h2', 'h3', 'h4', 'h5', 'h6'] as const)[level - 1] ?? 'h6'
      blocks.push(<Tag key={key} className={css.heading}>{inline(heading[2] ?? '', key)}</Tag>)
      index += 1
      continue
    }
    if (/^---+$/u.test(line)) {
      blocks.push(<hr key={key} className={css.rule} />)
      index += 1
      continue
    }
    if (line.startsWith('> ')) {
      const quote: string[] = []
      while (index < lines.length && (lines[index] ?? '').startsWith('> ')) {
        quote.push((lines[index] ?? '').slice(2))
        index += 1
      }
      blocks.push(<blockquote key={key} className={css.quote}>{inline(quote.join(' '), key)}</blockquote>)
      continue
    }
    if (/^\s*([-*]|\d+\.)\s+/u.test(line)) {
      const ordered = /^\s*\d+\.\s+/u.test(line)
      const items: ReactNode[] = []
      let itemIndex = 0
      while (index < lines.length && /^\s*([-*]|\d+\.)\s+/u.test(lines[index] ?? '')) {
        const content = (lines[index] ?? '').replace(/^\s*([-*]|\d+\.)\s+/u, '')
        items.push(<li key={key + String(itemIndex)}>{inline(content, key + String(itemIndex))}</li>)
        itemIndex += 1
        index += 1
      }
      blocks.push(ordered ? <ol key={key} className={css.list}>{items}</ol> : <ul key={key} className={css.list}>{items}</ul>)
      continue
    }
    if (line.trim() === '') {
      index += 1
      continue
    }
    const paragraph: string[] = []
    while (index < lines.length) {
      const next = lines[index] ?? ''
      if (next.trim() === '' || /^(#{1,6})\s+/u.test(next) || next.startsWith('```') || next.startsWith('> ') || /^---+$/u.test(next)) break
      paragraph.push(next)
      index += 1
    }
    blocks.push(<p key={key} className={css.paragraph}>{inline(paragraph.join(' '), key)}</p>)
  }
  return <div className={css.page}>{blocks}</div>
}
