/**
 * The editable code surface: a syntax-highlighted layer under a transparent
 * textarea, a line-number gutter with git marks, and a find/replace bar.
 *
 * Editing stays native — the textarea owns the caret, selection, IME and
 * accessibility — while the highlighted layer behind it carries the colours
 * Shiki assigns through the theme's `--shiki-*` properties. The gutter reads the
 * comparison the panel loaded, and the find bar drives the same textarea rather
 * than a second editing model.
 */
import { useCallback, useMemo, useRef, useState } from 'react'
import type { CSSProperties, KeyboardEvent, ReactNode, UIEvent } from 'react'
import { languageForPath, useCodeHighlighter, type HighlightSpan } from '@deepseek-ai/dsh-client-ui-primitives'
import type { GitMark } from './marks.ts'
import css from './CodeEditor.module.css'

/** The find bar's product copy, supplied by the panel's dictionary. */
export interface CodeEditorLabels {
  readonly find: string
  readonly replace: string
  readonly next: string
  readonly previous: string
  readonly replaceOne: string
  readonly replaceAll: string
  readonly close: string
  readonly noMatches: string
}

/** Props assembled by the Editor panel for one open document. */
export interface CodeEditorProps {
  /** The buffer's full text. */
  readonly value: string
  /** The document's name, which selects the grammar. */
  readonly name: string
  /** The accessible name for the editing surface. */
  readonly ariaLabel: string
  /** Receives every buffer change. */
  readonly onChange: (text: string) => void
  /** Receives the selection offsets on every move. */
  readonly onSelect: (start: number, end: number) => void
  /** Hand the current selection to the composer (the editor's Cmd+L). */
  readonly onReference: () => void
  /** The panel's own key handling (Tab indent and save). */
  readonly onKeyDown: (event: KeyboardEvent<HTMLTextAreaElement>) => void
  /** Per-line git marks from the file's comparison, keyed by one-based line. */
  readonly marks?: ReadonlyMap<number, GitMark> | undefined
  /** Find and replace copy. */
  readonly labels: CodeEditorLabels
}

/** One line's rendered height; the gutter, the layers and this agree. */
const LINE_HEIGHT = 20

/** One match in the buffer. */
interface Match {
  readonly start: number
  readonly end: number
}

/** One rendered piece of a line: a highlighted run, cut at the find matches. */
interface Segment {
  readonly text: string
  readonly style: CSSProperties
  readonly match: boolean
  readonly current: boolean
}

/**
 * Split one line's highlighted runs at the find matches that cross them.
 * @param runs - the line's Shiki runs, in order.
 * @param lineStart - the line's offset in the buffer.
 * @param matches - every match in the buffer.
 * @param currentStart - the focused match's offset, when there is one.
 * @returns the segments to render, in reading order.
 */
function segmentsOf(
  runs: readonly HighlightSpan[], lineStart: number, matches: readonly Match[], currentStart: number | undefined,
): readonly Segment[] {
  const segments: Segment[] = []
  const push = (text: string, style: CSSProperties, match: Match | undefined): void => {
    if (text === '') return
    segments.push({ text, style, match: match !== undefined, current: match !== undefined && match.start === currentStart })
  }
  let offset = 0
  for (const run of runs) {
    const runStart = lineStart + offset
    const runEnd = runStart + run.text.length
    const overlaps = matches
      .filter(match => match.end > runStart && match.start < runEnd)
      .map(match => ({ start: Math.max(match.start, runStart) - runStart, end: Math.min(match.end, runEnd) - runStart, match }))
      .sort((left, right) => left.start - right.start)
    let cursor = 0
    for (const overlap of overlaps) {
      if (overlap.start > cursor) push(run.text.slice(cursor, overlap.start), run.style, undefined)
      push(run.text.slice(overlap.start, overlap.end), run.style, overlap.match)
      cursor = Math.max(cursor, overlap.end)
    }
    if (cursor < run.text.length) push(run.text.slice(cursor), run.style, undefined)
    offset += run.text.length
  }
  return segments
}

/** One-based line and column of a caret offset. */
function caretOf(text: string, offset: number): { line: number; column: number } {
  let line = 1
  let lineStart = 0
  for (let index = 0; index < offset && index < text.length; index += 1) {
    if (text[index] === '\n') {
      line += 1
      lineStart = index + 1
    }
  }
  return { line, column: offset - lineStart + 1 }
}

/**
 * The highlighted surface, its gutter, its find bar, and the caret readout.
 * @param props - the buffer, its name, its marks, and the panel's callbacks.
 * @returns the editable code surface.
 */
export function CodeEditor({
  value, name, ariaLabel, onChange, onSelect, onReference, onKeyDown, marks, labels,
}: CodeEditorProps): ReactNode {
  const highlighter = useCodeHighlighter(languageForPath(name))
  const lines = useMemo(() => value.split('\n'), [value])
  const spans = useMemo(() => highlighter(value), [highlighter, value])
  const highlight = useRef<HTMLPreElement>(null)
  const gutter = useRef<HTMLDivElement>(null)
  const input = useRef<HTMLTextAreaElement>(null)
  const [caret, setCaret] = useState({ line: 1, column: 1 })
  const [findOpen, setFindOpen] = useState(false)
  const [query, setQuery] = useState('')
  const [replacement, setReplacement] = useState('')
  const [cursor, setCursor] = useState(0)
  const lineStarts = useMemo(() => {
    const starts: number[] = []
    let offset = 0
    for (const line of lines) {
      starts.push(offset)
      offset += line.length + 1
    }
    return starts
  }, [lines])

  const matches = useMemo<readonly Match[]>(() => {
    if (query === '') return []
    const haystack = value.toLowerCase()
    const needle = query.toLowerCase()
    const found: Match[] = []
    let index = haystack.indexOf(needle)
    while (index !== -1) {
      found.push({ start: index, end: index + needle.length })
      index = haystack.indexOf(needle, index + Math.max(1, needle.length))
    }
    return found
  }, [query, value])
  const current = matches.length === 0 ? -1 : Math.min(cursor, matches.length - 1)

  /** Mirror the textarea's scroll onto the two layers it scrolls. */
  const sync = useCallback((target: HTMLTextAreaElement): void => {
    if (highlight.current !== null) {
      highlight.current.scrollTop = target.scrollTop
      highlight.current.scrollLeft = target.scrollLeft
    }
    if (gutter.current !== null) gutter.current.scrollTop = target.scrollTop
  }, [])

  const track = (target: HTMLTextAreaElement): void => {
    setCaret(caretOf(target.value, target.selectionStart))
    onSelect(target.selectionStart, target.selectionEnd)
    sync(target)
  }

  const onScroll = (event: UIEvent<HTMLTextAreaElement>): void => { sync(event.currentTarget) }

  /** Select one match and bring it into view. */
  const reveal = (index: number): void => {
    const match = matches[index]
    const target = input.current
    if (match === undefined || target === null) return
    target.focus()
    target.setSelectionRange(match.start, match.end)
    const line = caretOf(value, match.start).line
    target.scrollTop = Math.max(0, (line - 1) * LINE_HEIGHT - target.clientHeight / 2)
    sync(target)
    setCaret({ line, column: 1 })
    onSelect(match.start, match.end)
  }

  const go = (delta: number): void => {
    if (matches.length === 0) return
    const index = (current + delta + matches.length) % matches.length
    setCursor(index)
    reveal(index)
  }

  const openFind = (): void => {
    setFindOpen(true)
    if (query !== '' && matches.length > 0) reveal(current === -1 ? 0 : current)
  }

  const closeFind = (): void => {
    setFindOpen(false)
    input.current?.focus()
  }

  const replaceOne = (): void => {
    const match = matches[current]
    if (match === undefined) return
    onChange(`${value.slice(0, match.start)}${replacement}${value.slice(match.end)}`)
  }

  const replaceAll = (): void => {
    if (query === '') return
    const escaped = query.replace(/[.*+?^${}()|[\]\\]/gu, '\\$&')
    onChange(value.replace(new RegExp(escaped, 'giu'), replacement))
  }

  const keyDown = (event: KeyboardEvent<HTMLTextAreaElement>): void => {
    // The editor's own Cmd+L: the textarea owns the selection, so this does not
    // depend on the global shortcut registry or the runtime's keybindings.
    if ((event.metaKey || event.ctrlKey) && event.key.toLowerCase() === 'l') {
      event.preventDefault()
      onReference()
      return
    }
    if ((event.metaKey || event.ctrlKey) && event.key.toLowerCase() === 'f') {
      event.preventDefault()
      openFind()
      return
    }
    if (findOpen && event.key === 'Escape') {
      event.preventDefault()
      closeFind()
      return
    }
    if (findOpen && event.key === 'Enter') {
      event.preventDefault()
      go(event.shiftKey ? -1 : 1)
      return
    }
    onKeyDown(event)
  }

  const barKeyDown = (event: KeyboardEvent<HTMLInputElement>): void => {
    if (event.key === 'Escape') {
      event.preventDefault()
      closeFind()
      return
    }
    if (event.key === 'Enter') {
      event.preventDefault()
      go(event.shiftKey ? -1 : 1)
    }
  }

  return (
    <div className={css.code}>
      <div ref={gutter} className={css.gutter} aria-hidden="true">
        {lines.map((_line, index) => (
          <span key={index} className={css.lineNumber} data-mark={marks?.get(index + 1)}>{index + 1}</span>
        ))}
      </div>
      <div className={css.surface}>
        <pre ref={highlight} className={css.highlight} aria-hidden="true">
          {spans === undefined
            ? value
            : lines.map((_line, index) => (
              <span key={index} className={css.line}>
                {segmentsOf(spans[index] ?? [], lineStarts[index] ?? 0, matches, matches[current]?.start)
                  .map((segment, segmentIndex) => (
                    <span
                      key={segmentIndex}
                      style={segment.style}
                      className={segment.current ? css.matchCurrent : segment.match ? css.match : undefined}
                    >
                      {segment.text}
                    </span>
                  ))}
                {'\n'}
              </span>
            ))}
        </pre>
        <textarea
          ref={input}
          className={css.input}
          aria-label={ariaLabel}
          spellCheck={false}
          value={value}
          onChange={(event) => { onChange(event.target.value); track(event.currentTarget) }}
          onSelect={(event) => { track(event.currentTarget) }}
          onClick={(event) => { track(event.currentTarget) }}
          onKeyUp={(event) => { track(event.currentTarget) }}
          onScroll={onScroll}
          onKeyDown={keyDown}
        />
        {findOpen && (
          <div className={css.findBar}>
            <input
              className={css.findInput}
              autoFocus
              value={query}
              placeholder={labels.find}
              aria-label={labels.find}
              onChange={(event) => { setQuery(event.target.value); setCursor(0) }}
              onKeyDown={barKeyDown}
            />
            <span className={css.findCount}>
              {matches.length === 0 ? labels.noMatches : `${String(current + 1)}/${String(matches.length)}`}
            </span>
            <button type="button" className={css.findButton} aria-label={labels.previous} onClick={() => { go(-1) }}>↑</button>
            <button type="button" className={css.findButton} aria-label={labels.next} onClick={() => { go(1) }}>↓</button>
            <input
              className={css.findInput}
              value={replacement}
              placeholder={labels.replace}
              aria-label={labels.replace}
              onChange={(event) => { setReplacement(event.target.value) }}
              onKeyDown={barKeyDown}
            />
            <button type="button" className={css.findButton} onClick={replaceOne}>{labels.replaceOne}</button>
            <button type="button" className={css.findButton} onClick={replaceAll}>{labels.replaceAll}</button>
            <button type="button" className={css.findButton} aria-label={labels.close} onClick={closeFind}>×</button>
          </div>
        )}
      </div>
      <div className={css.status} aria-hidden="true">
        <span>{'Ln '}{caret.line}{', Col '}{caret.column}</span>
        <span>{'Spaces: 2'}</span>
        <span>{'UTF-8'}</span>
        <span>{languageForPath(name) ?? 'text'}</span>
      </div>
    </div>
  )
}
